type QueuedMutation = {
  id: string;
  type: string;
  payload: unknown;
  timestamp: number;
};

async function queueOrExecute(
  mutation: QueuedMutation,
  execute: (payload: unknown) => Promise<void>,
  queryClient: any
) {
  if (!navigator.onLine) {
    const pending: QueuedMutation[] = JSON.parse(
      localStorage.getItem('mutationQueue') || '[]'
    );
    pending.push(mutation);
    localStorage.setItem('mutationQueue', JSON.stringify(pending));
    queryClient.setQueryData(['todos'], (old: any) => [
      ...old,
      { ...mutation.payload, _pending: true },
    ]);
    return;
  }

  await execute(mutation.payload);
  queryClient.invalidateQueries({ queryKey: ['todos'] });
}

async function processQueue(
  execute: (payload: unknown) => Promise<void>,
  queryClient: any
) {
  const pending: QueuedMutation[] = JSON.parse(
    localStorage.getItem('mutationQueue') || '[]'
  );

  for (const mutation of pending) {
    try {
      await execute(mutation.payload);
    } catch (error) {
      console.error('Failed to replay mutation:', mutation.id, error);
      break;
    }
  }

  localStorage.removeItem('mutationQueue');
  queryClient.invalidateQueries({ queryKey: ['todos'] });
}

window.addEventListener('online', () => processQueue(execute, queryClient));

function addToQueue(mutation: QueuedMutation) {
  const pending: QueuedMutation[] = JSON.parse(
    localStorage.getItem('mutationQueue') || '[]'
  );

  // Deduplicate by mutation id
  const filtered = pending.filter((m) => m.id !== mutation.id);
  filtered.push(mutation);

  localStorage.setItem('mutationQueue', JSON.stringify(filtered));
}

// Usage
addToQueue({
  id: crypto.randomUUID(),
  type: 'ADD_TODO',
  payload: { title: 'Buy milk' },
  timestamp: Date.now(),
});
